pessoas:["Bartolo Longo, beatificado em 1980"],
fatos:["A basílica foi consagrada em 1891.","Bartolo Longo foi beatificado por João Paulo II em 1980.","A Súplica a Nossa Senhora do Rosário, de sua autoria, é rezada em 8 de maio e na primeira domingo de outubro."],
relatos:["O núcleo da devoção é a pintura do Rosário, e não uma aparição."],
msgs:["Não há mensagem textual."],
